import re
from collections import Counter

def classify_document(text: str, categories: list[str]) -> str:
    # Simple keyword‑based classifier
    keywords = {
        "brand": ["brand", "eld", "brinnande", "rök"],
        "översvämning": ["översvämning", "vattenskada", "flod", "stormvatten"],
        "kraftavbrott": ["strömavbrott", "elavbrott", "kraft", "blackout"],
        "pandemi": ["pandemi", "infektion", "smittspridning", "virus"],
        "terrorism": ["terror", "attack", "explosion", "bomb"],
    }

    # Normalisera text
    words = re.findall(r"\b\w+\b", text.lower())

    # Räkna träffar per kategori
    scores = Counter()
    for cat, keys in keywords.items():
        for k in keys:
            scores[cat] += sum(1 for w in words if k in w)

    # Filtrera på tillåtna kategorier
    valid_scores = {c: scores[c] for c in categories if c in scores}
    if not valid_scores:
        return "okänt"

    # Välj kategori med högst poäng
    return max(valid_scores, key=valid_scores.get)
