from collections import Counter
from datetime import datetime, timedelta

def detect_brute_force(auth_log: list[dict], threshold: int = 5) -> list[str]:
    """
    auth_log: list of dicts with at least 'ip', 'status' ('fail'/'success'), 'timestamp' (ISO string)
    Returns list of IPs with >threshold failed attempts within any 5‑minute window.
    """
    # group failures by IP
    failures = {}
    for entry in auth_log:
        if entry.get("status") != "fail":
            continue
        ip = entry["ip"]
        ts = datetime.fromisoformat(entry["timestamp"])
        failures.setdefault(ip, []).append(ts)

    suspicious = set()
    window = timedelta(minutes=5)

    for ip, times in failures.items():
        times.sort()
        start = 0
        for end in range(len(times)):
            while times[end] - times[start] > window:
                start += 1
            if end - start + 1 > threshold:
                suspicious.add(ip)
                break

    return list(suspicious)
```

