from scapy.all import rdpcap, DNSQR, DNSRR
import re
from collections import Counter

def _entropy(s: str) -> float:
    probs = [float(c) / len(s) for c in Counter(s).values()]
    return -sum(p * (0 if p == 0 else __import__('math').log2(p)) for p in probs)

def analyze_dns_traffic(pcap_file: str) -> dict:
    pkts = rdpcap(pcap_file)
    domains = []
    for pkt in pkts:
        if pkt.haslayer(DNSQR):
            domains.append(pkt[DNSQR].qname.decode().rstrip('.'))
        if pkt.haslayer(DNSRR):
            domains.append(pkt[DNSRR].rrname.decode().rstrip('.'))

    suspicious = set()
    for d in domains:
        # simple DGA detection: high entropy or long random-looking label
        labels = d.split('.')
        if any(len(l) > 12 and _entropy(l) > 3.5 for l in labels):
            suspicious.add(d)
        # tunneling/exfil: many subdomains in a single query
        if len(labels) > 5 and sum(len(l) for l in labels) > 30:
            suspicious.add(d)

    return {
        "total_queries": len(domains),
        "unique_domains": len(set(domains)),
        "suspicious_domains": list(suspicious)
    }
