import re
from pathlib import Path

def harden_ssh_config(config_path: str) -> dict:
    """
    Analyzes an ssh_config file and returns recommendations for hardening.
    Returns a dict: {line_number: recommendation}.
    """
    recommendations = {}
    cfg = Path(config_path).read_text().splitlines()
    for i, line in enumerate(cfg, 1):
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue

        key, _, value = stripped.partition(' ')
        key = key.lower()
        value = value.strip()

        # Insecure settings checks
        if key == 'protocol' and value != '2':
            recommendations[i] = "Set Protocol 2 (remove older versions)."
        elif key == 'hostkeyalgorithms' and re.search(r'dss|ssh-dss', value, re.I):
            recommendations[i] = "Remove DSA algorithms; use stronger algorithms."
        elif key == 'ciphers' and re.search(r'3des-cbc|blowfish|arcfour', value, re.I):
            recommendations[i] = "Remove weak ciphers; prefer aes256-gcm@openssh.com, chacha20-poly1305."
        elif key == 'macs' and re.search(r'hmac-md5|hmac-sha1', value, re.I):
            recommendations[i] = "Remove weak MACs; prefer hmac-sha2-512, hmac-sha2-256."
        elif key == 'permitrootlogin' and value.lower() != 'no':
            recommendations[i] = "Set PermitRootLogin no."
        elif key == 'passwordauthentication' and value.lower() != 'no':
            recommendations[i] = "Set PasswordAuthentication no (use keys)."
        elif key == 'pubkeyauthentication' and value.lower() != 'yes':
            recommendations[i] = "Set PubkeyAuthentication yes."
        elif key == 'allowagents' and value.lower() != 'no':
            recommendations[i] = "Set AllowAgentForwarding no."
        elif key == 'x11forwarding' and value.lower() != 'no':
            recommendations[i] = "Set X11Forwarding no."
        elif key == 'loglevel' and value.lower() not in ('verbose', 'info'):
            recommendations[i] = "Set LogLevel VERBOSE or INFO."
        elif key == 'maxauthtries' and (not value.isdigit() or int(value) > 3):
            recommendations[i] = "Set MaxAuthTries to 3 or fewer."
    return recommendations
